<?php
declare(strict_types=1);
namespace App\Infrastructure\Persistence\PDO;
use App\Domain\Quiz\QuizSession;use App\Domain\Quiz\QuizSessionId;use App\Domain\Quiz\QuizSessionRepository;use PDO;
final class PdoQuizSessionRepository implements QuizSessionRepository { public function __construct(private PDO $pdo) {} public function nextId(): QuizSessionId { return QuizSessionId::new(); } public function generateAccessCode(): string { return str_pad((string) random_int(0,9999),4,'0',STR_PAD_LEFT); } public function isCodeTaken(string $code): bool { $st=$this->pdo->prepare('SELECT 1 FROM quiz_sessions WHERE access_code=:c LIMIT 1'); $st->execute(['c'=>$code]); return $st->fetch()!==false; } public function save(QuizSession $s): void { $st=$this->pdo->prepare('INSERT INTO quiz_sessions (id,user_id,access_code,expires_at,status,topic,questions_json) VALUES (:id,:userId,:code,:expiresAt,:status,:topic,:questionsJson) ON CONFLICT(id) DO UPDATE SET expires_at=excluded.expires_at,status=excluded.status,topic=excluded.topic,questions_json=excluded.questions_json'); $st->execute(['id'=>$s->id()->value(),'userId'=>$s->userId(),'code'=>$s->accessCode(),'expiresAt'=>$s->expiresAt()->format(DATE_ATOM),'status'=>$s->status(),'topic'=>$s->topic(),'questionsJson'=>$s->questionsJson()]); } public function byCode(string $code): ?QuizSession { $st=$this->pdo->prepare('SELECT * FROM quiz_sessions WHERE access_code=:c'); $st->execute(['c'=>$code]); $row=$st->fetch(); return $row===false?null:$this->hydrate($row);} public function byId(QuizSessionId $id): ?QuizSession { $st=$this->pdo->prepare('SELECT * FROM quiz_sessions WHERE id=:id'); $st->execute(['id'=>$id->value()]); $row=$st->fetch(); return $row===false?null:$this->hydrate($row);} private function hydrate(array $r): QuizSession { return QuizSession::reconstitute(QuizSessionId::fromString((string)$r['id']),(string)$r['user_id'],(string)$r['access_code'],new \DateTimeImmutable((string)$r['expires_at']),(string)$r['status'],(string)$r['topic'],$r['questions_json']!==null?(string)$r['questions_json']:null); }}
